// Model templates loaded from public/models/models.glb (generated by
// `npm run models` from modeldefs.ts). Call loadModels() before building a scene.

import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { Side } from '../sim/entities';
import type { VehicleType } from '../sim/tuning';
import { MATERIALS, ModelBuilder, mesh } from './build';
import { PALETTES as DEF_PALETTES, type Palette } from './modeldefs';

export type { Palette };
export const PALETTES: Record<Side, Palette> = { 0: DEF_PALETTES['0'], 1: DEF_PALETTES['1'] };
export type Variant = Side | 'wreck';
export type VehicleModelKind = VehicleType | 'drone' | 'ptank';

const templates = new Map<string, THREE.Object3D>();

export async function loadModels(url = `${import.meta.env.BASE_URL}models/models.glb`) {
  const gltf = await new GLTFLoader().loadAsync(url);
  for (const root of [...gltf.scene.children]) {
    root.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const name = (Array.isArray(m.material) ? m.material[0] : m.material).name as keyof typeof MATERIALS;
      m.material = MATERIALS[name] ?? MATERIALS.matte;
      m.castShadow = name !== 'glass';
      m.receiveShadow = true;
    });
    templates.set(root.name, root);
  }
}

function template(id: string): THREE.Object3D {
  // GLTFLoader sanitises node names ('.' becomes '_').
  const t = templates.get(THREE.PropertyBinding.sanitizeNodeName(id));
  if (!t) throw new Error(`model ${id} not loaded`);
  return t;
}

/** Finds a part by name; GLTFLoader makes repeated names unique by appending _1, _2, ... */
function part(root: THREE.Object3D, name: string): THREE.Object3D | null {
  const re = new RegExp(`^${name}(_\\d+)?$`);
  let hit: THREE.Object3D | null = null;
  root.traverse((o) => {
    if (!hit && o !== root && re.test(o.name)) hit = o;
  });
  return hit;
}

export interface VehicleModel {
  root: THREE.Group;
  turret: THREE.Object3D | null;
  rotor: THREE.Object3D | null;
  tailRotor: THREE.Object3D | null;
}

const discMat = new THREE.MeshBasicMaterial({ color: '#ffffff', transparent: true, opacity: 0.08, side: THREE.DoubleSide, depthWrite: false });
const discGeo = new THREE.CircleGeometry(22, 24).rotateX(-Math.PI / 2);

export function vehicleModel(kind: VehicleModelKind, variant: Variant): VehicleModel {
  const id = `${kind === 'ptank' ? 'tank' : kind}.${variant}`;
  const inner = template(id).clone(true);
  inner.position.set(0, 0, 0);
  const root = new THREE.Group();
  root.add(inner);
  root.rotation.order = 'YXZ';
  const find = (n: string) => part(inner, n);
  const rotor = find('rotor');
  if (rotor && kind === 'heli') {
    const disc = new THREE.Mesh(discGeo, discMat);
    disc.renderOrder = 2;
    disc.castShadow = false;
    rotor.add(disc);
  }
  if (kind === 'drone') root.scale.setScalar(0.8);
  return { root, turret: find('turret'), rotor, tailRotor: find('tailRotor') };
}

export interface StructureGeo {
  base: THREE.BufferGeometry;
  head?: THREE.BufferGeometry;
  headY: number;
}

export function structureGeometry(kind: 'tower' | 'bunker' | 'turret' | 'guard' | 'aa' | 'wall', side: Side): StructureGeo {
  const t = template(`${kind}.${side}`);
  const base = (part(t, 'base') as THREE.Mesh).geometry;
  const headNode = (part(t, 'head') as THREE.Mesh | null) ?? undefined;
  return { base, head: headNode?.geometry, headY: headNode?.position.y ?? 10 };
}

export function treeGeometries(): THREE.BufferGeometry[] {
  return ['tree.pine', 'tree.broadleaf'].map((id) => (part(template(id), 'base') as THREE.Mesh).geometry);
}

export function flagModel(colour: string): { root: THREE.Group; pennant: THREE.Object3D } {
  const root = new THREE.Group();
  const pole = new ModelBuilder().cyl(0.9, 0.9, 28, 6, '#ece4cf', 0, 14, 0).sphere(1.6, '#f0c24a', 0, 28.5, 0).build();
  root.add(mesh(pole, MATERIALS.matte));
  const pen = mesh(new ModelBuilder().box(15, 9, 0.8, colour, 7.5, 0, 0).build(), MATERIALS.matte);
  pen.position.set(0.5, 23, 0);
  root.add(pen);
  return { root, pennant: pen };
}
